{
    return \Datamunge\Rosetta\Runtime::call(215, [...\array_slice([$successes1, $n1, $successes2, $n2, $alternative, $correct, $confLevel], 0, \func_num_args())]);
}

/**
 * Exact binomial test with Clopper-Pearson confidence bounds, like R binom.test().
